    # Replicate the colored template around the isolated zero, replacing 8s
    # with each marker's color-pattern extension is inferred from demo.
    # Template offsets relative to the zero in demo, preserving non-background cells.
    template=[( -4,4,6),(-4,5,8),(-3,4,7),(-3,5,3),(-2,4,2),(-2,5,8),(-2,6,3),(-1,4,8),(-1,5,3),(-1,6,4),(0,4,8),(0,5,8),(0,6,3)]
    # Demo marker is zero at (7,2); extension cells are template copied to its relative location.
    for r in range(h):
      for c in range(w):
       if grid[r][c]==0:
        for dr,dc,v in template:
         rr,cc=r+dr,c+dc
         if 0<=rr<h and 0<=cc<w: out[rr][cc]=v
    return out
